"""Learning tasks for the algorithm curriculum."""
import json

def bundle(**files):
    return json.dumps(files, ensure_ascii=False)

def extend_content(chapters, exercises, add):
    add('baze', 'Citire și afișare mixtă', 'Citește pe trei linii doi întregi, două numere reale și două caractere (perechile sunt separate prin spațiu). Afișează întreg, real, caracter, întreg, real, caracter pe o linie; numerele reale au două zecimale.', 'Convertește fiecare pereche potrivit tipului ei. Formatează fiecare real prin :.2f.', 'a, b = map(int, input().split())\nx, y = map(float, input().split())\nc, d = input().split()\nprint(a, f"{x:.2f}", c, b, f"{y:.2f}", d)', [('1 2\n3.5 4\na b','1 3.50 a 2 4.00 b'),('-2 0\n-1.25 0\nx y','-2 -1.25 x 0 0.00 y'),('5 5\n1 1\nc d','5 1.00 c 5 1.00 d')])
    add('baze', 'Identitate și egalitate', 'Citește o listă de întregi. Creează b = a și c = a.copy(). Afișează, în ordine, a == b, a is b, a == c, a is c.', '== compară conținutul listelor; is verifică dacă numele se referă la același obiect.', 'a = list(map(int, input().split()))\nb = a\nc = a.copy()\nprint(a == b, a is b, a == c, a is c)', [('1 2','True True True False'),('\n','True True True False'),('-1','True True True False')])
    add('decizii', 'Ziua următoare fără datetime', 'Citește zi luna an pe o linie: o dată validă din anii 1900..2099. Calculează ziua următoare fără datetime. Afișează zi.luna.an fără zerouri suplimentare.', 'Calculează mai întâi numărul zilelor din februarie, apoi tratează trecerea lunii și a anului.', 'z, l, a = map(int, input().split())\nzile = [31, 29 if a % 400 == 0 or a % 4 == 0 and a % 100 != 0 else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]\nz += 1\nif z > zile[l - 1]:\n    z = 1\n    l += 1\nif l == 13:\n    l = 1\n    a += 1\nprint(f"{z}.{l}.{a}")', [('28 2 2000','29.2.2000'),('28 2 1900','1.3.1900'),('31 12 2026','1.1.2027')], 'Aplicare')
    add('liste', 'Cea mai mare creștere', 'Citește n ≥ 2, apoi n cursuri valutare pozitive pe o linie. Afișează prima pereche de zile consecutive cu diferența maximă (numerotate de la 1) și diferența cu două zecimale. Diferența poate fi negativă.', 'Compară a[i+1]-a[i]; actualizează numai pentru o diferență strict mai mare.', 'n = int(input())\na = list(map(float, input().split()))\ni = max(range(n - 1), key=lambda k: a[k + 1] - a[k])\nprint(i + 1, i + 2, f"{a[i + 1] - a[i]:.2f}")', [('6\n4.25 4.05 4.25 4.48 4.30 4.40','3 4 0.23'),('3\n5 4 3','1 2 -1.00'),('2\n1 1','1 2 0.00')], 'Aplicare')
    add('bucle', 'Economiile lui Gigel', 'Prima linie este prețul s > 0; a doua conține depunerile zilnice pozitive, suficiente pentru cumpărare. Afișează prima zi când suma ajunge la s, media depunerilor până atunci cu trei zecimale și restul după cumpărare.', 'Oprește adunarea la prima sumă ≥ s; media se calculează numai pentru zilele folosite.', 's = int(input())\na = list(map(int, input().split()))\ntotal = 0\nfor i, x in enumerate(a, 1):\n    total += x\n    if total >= s:\n        print(i, f"{total / i:.3f}", total - s)\n        break', [('10\n3 4 5 8','3 4.000 2'),('5\n5 2','1 5.000 0'),('7\n2 2 3','3 2.333 0')], 'Aplicare')
    add('bucle', 'Fibonacci în interval', 'Citește 0 ≤ a ≤ b ≤ 10^9. Afișează cel mai mic număr Fibonacci din [a,b] sau NU dacă nu există. F(0)=0, F(1)=1.', 'Generează termeni până când primul atinge a, apoi compară cu b.', 'a, b = map(int, input().split())\nx, y = 0, 1\nwhile x < a:\n    x, y = y, x + y\nprint(x if x <= b else "NU")', [('10 20','13'),('4 4','NU'),('0 0','0')])
    add('bucle', 'Piramida', 'Citește 1 ≤ n ≤ 15. Afișează n linii: linia i conține 1..i, separate prin spațiu.', 'Bucla exterioară alege linia; cea interioară generează valorile ei.', 'n = int(input())\nfor i in range(1, n + 1):\n    print(*range(1, i + 1))', [('3','1\n1 2\n1 2 3'),('1','1'),('2','1\n1 2')])
    add('bucle', 'Numere din aceleași cifre', 'Citește un întreg pozitiv. Afișează cel mai mic și cel mai mare întreg format folosind exact cifrele sale; primul nu poate începe cu 0.', 'După sortare crescătoare, mută prima cifră nenulă înaintea zerourilor.', 's = sorted(input())\ni = next(i for i, c in enumerate(s) if c != "0")\ns[0], s[i] = s[i], s[0]\nprint("".join(s), "".join(sorted(s, reverse=True)))', [('812383','123388 883321'),('1002','1002 2100'),('7','7 7')], 'Aplicare')
    add('bucle', 'Minim și frecvență', 'Citește o listă nevidă de întregi. Afișează minimul și numărul aparițiilor lui, într-o singură parcurgere.', 'La un minim nou, resetează contorul la 1; la egalitate, îl crești.', 'a = list(map(int, input().split()))\nm = a[0]\nnr = 0\nfor x in a:\n    if x < m:\n        m, nr = x, 1\n    elif x == m:\n        nr += 1\nprint(m, nr)', [('3 1 2 1','1 2'),('-2 -2 -2','-2 3'),('5','5 1')])
    add('bucle', 'Puterile lui 2', 'Citește 0 ≤ a ≤ b ≤ 10^9. Afișează crescător toate puterile lui 2 din [a,b], inclusiv 2^0=1. Dacă nu există, afișează NU.', 'Începe cu 1 și dublează până depășești b.', 'a, b = map(int, input().split())\np = 1\nv = []\nwhile p <= b:\n    if p >= a:\n        v.append(p)\n    p *= 2\nprint(*v if v else ["NU"])', [('10 100','16 32 64'),('0 1','1'),('5 7','NU')])
    add('bucle', 'Cifra de control', 'Citește un număr natural. Adună repetat cifrele până rămâne o singură cifră; afișeaz-o.', 'O singură sumă nu ajunge mereu: pentru 99 obții întâi 18, apoi 9.', 'n = int(input())\nwhile n >= 10:\n    n = sum(map(int, str(n)))\nprint(n)', [('99','9'),('0','0'),('12345','6')])
    add('bucle', 'Număr de divizori', 'Citește 1 ≤ n ≤ 10^9. Numără divizorii pozitivi ai lui n în O(sqrt(n)).', 'Divizorii vin în perechi d, n//d; rădăcina exactă se numără o singură dată.', 'n = int(input())\nd = 1\nnr = 0\nwhile d * d <= n:\n    if n % d == 0:\n        nr += 1 if d * d == n else 2\n    d += 1\nprint(nr)', [('1','1'),('36','9'),('13','2')], 'Aplicare')
    add('bucle', 'Zerourile lui n factorial', 'Citește 0 ≤ n ≤ 10^9. Afișează numărul de zerouri finale ale lui n!, fără a calcula factorialul.', 'Numără factorii 5: n//5 + n//25 + ... . Factorii 2 sunt suficienți.', 'n = int(input())\ns = 0\nwhile n:\n    n //= 5\n    s += n\nprint(s)', [('25','6'),('0','0'),('100','24')], 'Aplicare')
    add('liste', 'Verifică vectorul creastă', 'Citește o listă nevidă de întregi. Afișează DA dacă este mai întâi nedescrescătoare, apoi necrescătoare. Una dintre porțiuni poate avea lungime 1.', 'După prima scădere, nu mai poate apărea o creștere.', 'a = list(map(int, input().split()))\ni = 1\nwhile i < len(a) and a[i] >= a[i - 1]:\n    i += 1\nwhile i < len(a) and a[i] <= a[i - 1]:\n    i += 1\nprint("DA" if i == len(a) else "NU")', [('1 3 3 2 1','DA'),('1 3 2 4','NU'),('5','DA')])
    add('siruri', 'Taie și centrează', 'Citește un cuvânt de 1..10 caractere. Afișează cuvântul centrat pe 10 caractere, apoi taie prima și ultima literă și repetă cât timp șirul este nevid. Spațiile contează exact.', 'center(10) returnează un șir nou; s[1:-1] elimină marginile.', 's = input()\nwhile s:\n    print(s.center(10))\n    s = s[1:-1]', [('abcd','   abcd   \n    bc    \n'),('x','    x     \n'),('abc','   abc    \n    b     \n')], compare='exact')
    add('siruri', 'Pozițiile fără suprapunere', 'Citește s și t nevid pe linii separate. Afișează toate pozițiile de început ale aparițiilor lui t în s, de la 0, fără suprapuneri; dacă nu există, afișează -1.', 'După o potrivire la p, reia find de la p+len(t). index ar ridica ValueError dacă nu există.', 's = input()\nt = input()\na = []\np = s.find(t)\nwhile p != -1:\n    a.append(p)\n    p = s.find(t, p + len(t))\nprint(*a if a else [-1])', [('abccabcababc\nabc','0 4 9'),('aaaaa\naa','0 2'),('xyz\na','-1')])
    add('siruri', 'Corectează cel mult p greșeli', 'Citește textul, forma greșită nevidă, forma corectă și p ≥ 0 pe patru linii. Afișează textul după primele p înlocuiri fără suprapunere, apoi OK dacă toate greșelile au fost corectate, altfel LIMITA.', 'replace(gresit, corect, p) limitează înlocuirile; count numără potrivirile fără suprapunere.', 's = input()\ngresit = input()\ncorect = input()\np = int(input())\nprint(s.replace(gresit, corect, p))\nprint("OK" if s.count(gresit) <= p else "LIMITA")', [('aa aa aa\naa\nb\n2','b b aa\nLIMITA'),('mere\nx\ny\n0','mere\nOK'),('aaaa\naa\nx\n2','xx\nOK')])
    add('siruri', 'Înlocuiește cuvântul întreg', 'Citește propoziția, cuvântul vechi și cel nou pe trei linii. Cuvintele sunt separate prin spații, virgulă, punct, !, ? sau ;. Înlocuiește numai cuvintele complete, păstrând separatorii.', 'Separă textul cu un grup capturant pentru separatori; înlocuiește numai tokenurile egale.', 'import re\ns = input()\na = input()\nb = input()\nprint("".join(b if x == a else x for x in re.split(r"([ ,.!?;]+)", s)))', [('ana banana, ana!\nana\nEva','Eva banana, Eva!'),('mere\nmere\npere','pere'),('x  xx\nx\ny','y  xx')], 'Aplicare')
    add('siruri', 'Decriptează Caesar', 'Citește text ASCII și k ≥ 0 pe două linii. Decriptează cifrul Caesar mutând literele cu k poziții la stânga, păstrând majusculele și celelalte caractere.', 'Folosește modulo 26, cu baze separate pentru A și a.', 's = input()\nk = int(input()) % 26\na = []\nfor c in s:\n    if "a" <= c <= "z" or "A" <= c <= "Z":\n        baza = ord("a") if c.islower() else ord("A")\n        c = chr((ord(c) - baza - k) % 26 + baza)\n    a.append(c)\nprint("".join(a))', [('Def ABC!\n3','Abc XYZ!'),('abc\n26','abc'),('A\n1','Z')], 'Aplicare')
    add('siruri', 'Revino din păsărească', 'Citește un text codificat corect: fiecare vocală ASCII a/e/i/o/u, inclusiv majusculă, a fost urmată de p și aceeași vocală. Decodează textul.', 'Copiază litera; după o vocală sari peste cele două caractere inserate.', 's = input()\na = []\ni = 0\nwhile i < len(s):\n    a.append(s[i])\n    i += 3 if s[i] in "aeiouAEIOU" else 1\nprint("".join(a))', [('Apa','A'),('meperepe','mere'),('xyz','xyz')], 'Aplicare')
    add('liste', 'Șterge segmentul minim în loc', 'Citește lista de întregi și apoi k, 1 ≤ k ≤ lungimea listei. Elimină prima subsecvență de lungime k cu sumă minimă; afișează lista rămasă. Nu construi o listă suplimentară pentru rezultat.', 'Menține suma unei ferestre glisante, apoi folosește del a[st:st+k].', 'a = list(map(int, input().split()))\nk = int(input())\ns = best = sum(a[:k])\nst = 0\nfor i in range(k, len(a)):\n    s += a[i] - a[i - k]\n    if s < best:\n        best, st = s, i - k + 1\ndel a[st:st + k]\nprint(*a)', [('5 1 2 9\n2','5 9'),('1 1 1\n1','1 1'),('3 2\n2','')], 'Aplicare')
    add('liste', 'Inserează după negative', 'Citește o listă de întregi. Inserează câte un 0 după fiecare valoare negativă, în aceeași listă; afișează rezultatul.', 'Parcurge de la dreapta la stânga pentru ca inserarea să nu schimbe indicii încă neprelucrați.', 'a = list(map(int, input().split()))\nfor i in range(len(a) - 1, -1, -1):\n    if a[i] < 0:\n        a.insert(i + 1, 0)\nprint(*a)', [('-1 2 -3','-1 0 2 -3 0'),('1 0','1 0'),('\n','')])
    add('liste', 'Ciurul lui Eratostene', 'Citește 0 ≤ n ≤ 100000. Afișează toate numerele prime ≤ n, în ordine crescătoare; dacă nu există, afișează NU.', 'Marchează multiplii fiecărui prim p, începând de la p*p.', 'n = int(input())\na = [True] * (n + 1)\np = 2\nwhile p * p <= n:\n    if a[p]:\n        for j in range(p * p, n + 1, p):\n            a[j] = False\n    p += 1\nb = [i for i in range(2, n + 1) if a[i]]\nprint(*b if b else ["NU"])', [('10','2 3 5 7'),('1','NU'),('2','2')], 'Aplicare')
    add('liste', 'Perechi egale disjuncte', 'Citește o listă cu valori naturale între 0 și 99. Numără maximum de perechi de elemente egale, fiecare poziție folosită cel mult o dată. Folosește un vector de frecvențe.', 'Pentru o valoare care apare f ori poți forma f//2 perechi.', 'f = [0] * 100\nfor x in map(int, input().split()):\n    f[x] += 1\nprint(sum(x // 2 for x in f))', [('1 1 1 2 2','2'),('0 0 0 0','2'),('\n','0')])
    add('liste', 'Triunghiul lui Pascal', 'Citește 1 ≤ n ≤ 12. Afișează primele n linii ale triunghiului lui Pascal, cu un spațiu între numere.', 'Marginile sunt 1; fiecare valoare interioară este suma celor două valori de deasupra.', 'n = int(input())\na = [1]\nfor _ in range(n):\n    print(*a)\n    a = [1] + [a[i] + a[i + 1] for i in range(len(a) - 1)] + [1]', [('4','1\n1 1\n1 2 1\n1 3 3 1'),('1','1'),('2','1\n1 1')], 'Aplicare')
    add('liste', 'Inserează o linie în matrice', 'Citește n m, apoi matricea și k, 0 ≤ k ≤ n. Inserează o linie de m zerouri înainte de linia cu indice k (indicii sunt de la 0; k=n înseamnă la sfârșit). Afișează matricea.', 'Construiește o linie nouă independentă și folosește insert.', 'n, m = map(int, input().split())\na = [list(map(int, input().split())) for _ in range(n)]\nk = int(input())\na.insert(k, [0] * m)\nfor row in a:\n    print(*row)', [('2 2\n1 2\n3 4\n1','1 2\n0 0\n3 4'),('1 1\n7\n0','0\n7'),('1 2\n1 2\n1','1 2\n0 0')])
    add('liste', 'Matrice șerpuită', 'Citește n m și matricea. Afișează toate valorile pe o linie, parcurgând prima linie de la stânga la dreapta, a doua invers și alternând.', 'Alege row sau row[::-1] după paritatea indicelui liniei.', 'n, m = map(int, input().split())\na = [list(map(int, input().split())) for _ in range(n)]\nb = []\nfor i, row in enumerate(a):\n    b.extend(row if i % 2 == 0 else row[::-1])\nprint(*b)', [('2 3\n1 2 3\n4 5 6','1 2 3 6 5 4'),('1 2\n7 8','7 8'),('3 1\n1\n2\n3','1 2 3')])
    add('liste', 'Copie în adâncime', 'Citește n m și o matrice. Creează o copie în adâncime, schimbă primul element din copie în 999, apoi afișează matricea originală. Definește copia folosind deepcopy.', 'O copie superficială copiază lista exterioară, dar păstrează referințele la linii.', 'from copy import deepcopy\nn, m = map(int, input().split())\na = [list(map(int, input().split())) for _ in range(n)]\nb = deepcopy(a)\nb[0][0] = 999\nfor row in a:\n    print(*row)', [('2 2\n1 2\n3 4','1 2\n3 4'),('1 1\n5','5'),('1 2\n0 -1','0 -1')], 'Aplicare')
    add('colectii', 'Sortare după cifre', 'Citește o listă de numere naturale. Sortează crescător după suma cifrelor, iar la egalitate descrescător după valoare.', 'Cheia este (suma_cifrelor(x), -x).', 'a = list(map(int, input().split()))\na.sort(key=lambda x: (sum(map(int, str(x))), -x))\nprint(*a)', [('11 45 20 810 179 81 1000','1000 20 11 810 81 45 179'),('12 21 3','21 12 3'),('\n','')])
    add('colectii', 'Impare înaintea parelor', 'Citește o listă de numere naturale. Afișează imparele crescător, apoi parele descrescător, folosind o singură sortare cu key.', 'Primul criteriu separă cele două grupuri, al doilea are semn diferit în fiecare grup.', 'a = list(map(int, input().split()))\na.sort(key=lambda x: (x % 2 == 0, x if x % 2 else -x))\nprint(*a)', [('4 3 2 1 6','1 3 6 4 2'),('0 2','2 0'),('7','7')])
    add('colectii', 'Reuniune și diferență simetrică', 'Citește două linii de întregi, posibil goale. Afișează reuniunea crescător pe prima linie și diferența simetrică crescător pe a doua.', 'A|B conține toate valorile; A^B conține valorile din exact una dintre mulțimi.', 'a = set(map(int, input().split()))\nb = set(map(int, input().split()))\nprint(*sorted(a | b))\nprint(*sorted(a ^ b))', [('1 2\n2 3','1 2 3\n1 3'),('1\n1','1\n'),('\n\n','\n')])
    add('colectii', 'Grupează cuvintele care rimează', 'Prima linie este p ≥ 1; a doua conține cuvinte lowercase. Grupează după ultimele p litere. Ordonează grupurile descrescător după numărul de cuvinte, apoi crescător după sufix; cuvintele din grup sunt descrescătoare lexicografic. Afișează un grup pe linie.', 'Folosește un dicționar cu sufixul drept cheie; sortarea are criterii pentru grupuri și pentru cuvinte.', 'p = int(input())\nd = {}\nfor x in input().split():\n    d.setdefault(x[-p:], []).append(x)\nfor key in sorted(d, key=lambda k: (-len(d[k]), k)):\n    print(*sorted(d[key], reverse=True))', [('2\nana dana mere pere prune bune','dana ana\nprune bune\npere mere'),('1\na ba c','ba a\nc'),('2\n\n','')], 'Aplicare')
    add('colectii', 'Aceleași litere, alte frecvențe', 'Citește cuvinte lowercase. Grupează-le după mulțimea literelor, păstrând numai grupurile cu minimum două cuvinte. În grup sortează după lungime, apoi lexicografic; grupurile au numărul literelor distincte descrescător, apoi cheia alfabetică crescător.', 'frozenset poate fi cheie de dicționar; aici aab și ab aparțin aceluiași grup.', 'd = {}\nfor x in input().split():\n    d.setdefault(frozenset(x), []).append(x)\nfor key in sorted(d, key=lambda k: (-len(k), "".join(sorted(k)))):\n    if len(d[key]) >= 2:\n        print(*sorted(d[key], key=lambda x: (len(x), x)))', [('aab ab abc cba x','abc cba\nab aab'),('x xx y','x xx'),('ana mere','')], 'Aplicare')
    add('functii', 'Modificare și reasignare', 'Citește o listă de întregi. Definește schimba(a): adaugă 9 în lista primită, apoi reasignează parametrul local a la [0]. Apelează funcția și afișează lista originală.', 'append modifică obiectul partajat; a=[0] schimbă numai numele local.', 'def schimba(a):\n    a.append(9)\n    a = [0]\na = list(map(int, input().split()))\nschimba(a)\nprint(*a)', [('1 2','1 2 9'),('\n','9'),('0','0 9')], requiredFunction='schimba')
    add('functii', 'Filtrare cu kwargs', 'Definește filtreaza(persoane, **criterii): returnează înregistrările care au toate perechile cheie-valoare cerute. Citește n, apoi n perechi nume grupa; ultima linie este grupa căutată. Afișează numele persoanelor potrivite în ordinea inițială.', 'all(p.get(k)==v for k,v in criterii.items()) verifică toate criteriile.', 'def filtreaza(persoane, **criterii):\n    return [p for p in persoane if all(p.get(k) == v for k, v in criterii.items())]\nn = int(input())\na = []\nfor _ in range(n):\n    nume, grupa = input().split()\n    a.append(dict(nume=nume, grupa=grupa))\ng = input()\nprint(*(p["nume"] for p in filtreaza(a, grupa=g)))', [('3\nAna 1\nDan 2\nEva 1\n1','Ana Eva'),('1\nBob 2\n1',''),('0\n1','')], 'Aplicare', requiredFunction='filtreaza')
    add('functii', 'Generator consumat pas cu pas', 'Citește n ≥ 0. Definește generator(n), care produce 0..n-1 prin yield. Apelează next(g,-1) de două ori, apoi afișează restul valorilor pe o altă linie.', 'Generatorul păstrează poziția între apeluri; nu reîncepe la fiecare next.', 'def generator(n):\n    for i in range(n):\n        yield i\ng = generator(int(input()))\nprint(next(g, -1), next(g, -1))\nprint(*g)', [('4','0 1\n2 3'),('1','0 -1\n'),('0','-1 -1\n')], requiredFunction='generator')
    add('functii', 'Cifre maxime și baza 2', 'Citește o linie de numere naturale pozitive. Definește concat_max(*numere), care concatenează cifra maximă a fiecărui număr. Afișează rezultatul, apoi DA dacă toate numerele conțin numai cifrele 0 și 1, altfel NU.', 'Dacă cifra maximă a fiecărui număr este 1, numerele pozitive au numai cifre binare.', 'def concat_max(*numere):\n    return int("".join(max(str(x)) for x in numere))\na = list(map(int, input().split()))\nprint(concat_max(*a))\nprint("DA" if all(max(str(x)) == "1" for x in a) else "NU")', [('4251 73 8 133','5783\nNU'),('1001 11 100','111\nDA'),('17','7\nNU')], 'Aplicare', requiredFunction='concat_max')
    add('fisiere', 'Corectează testul și acordă nota', 'date.in conține 0..9 înmulțiri de forma a*b=c, cu numere naturale. Scrie în date.out fiecare expresie urmată de Corect sau Gresit și rezultatul corect; ultima linie este Nota X, unde X=1+numărul răspunsurilor corecte.', 'Separă întâi la =, apoi la *. Nu folosi eval pentru citirea datelor.', 'nota = 1\nwith open("date.in") as f, open("date.out", "w") as out:\n    for line in f:\n        expr = line.strip()\n        left, c = expr.split("=")\n        a, b = map(int, left.split("*"))\n        if a * b == int(c):\n            nota += 1\n            print(expr, "Corect", file=out)\n        else:\n            print(expr, "Gresit", a * b, file=out)\n    print("Nota", nota, file=out)', [('3*4=11\n2*10=20','3*4=11 Gresit 12\n2*10=20 Corect\nNota 2'),('0*5=0','0*5=0 Corect\nNota 2'),('','Nota 1')], 'Aplicare', inputFile='date.in', outputFile='date.out')
    add('fisiere', 'Cele mai mici patru, în ordinea inițială', 'date.in conține pe fiecare linie o listă de întregi. Scrie în date.out cele mai mici patru valori ale fiecărei linii, păstrând ordinea apariției și multiplicitatea. Dacă sunt mai puțin de patru, păstrează toate valorile.', 'Sortează pentru a afla ce valori trebuie păstrate, apoi consumă frecvențele lor în ordinea originală.', 'from collections import Counter\nwith open("date.in") as f, open("date.out", "w") as out:\n    for line in f:\n        a = list(map(int, line.split()))\n        counts = Counter(sorted(a)[:4])\n        b = []\n        for x in a:\n            if counts[x]:\n                b.append(x)\n                counts[x] -= 1\n        print(*b, file=out)', [('9 3 1 2 4\n7 8','3 1 2 4\n7 8'),('2 1 2 1 2','2 1 2 1'),('\n','')], 'Aplicare', inputFile='date.in', outputFile='date.out')
    add('colectii', 'Frecvențe filtrate și sortare multiplă', 'Citește K ≥ 1 pe prima linie și text ASCII pe a doua. Transformă în lowercase și tratează ,.!?;: ca separatori. Afișează cuvintele cu minimum K apariții, un cuvânt și frecvența pe linie, sortate după frecvență descrescătoare, lungime descrescătoare și lexicografic crescător.', 'Construiește Counter după normalizare; cheia de sortare are trei componente.', 'from collections import Counter\nk = int(input())\ns = input().lower().translate(str.maketrans({c: " " for c in ",.!?;:"}))\nd = Counter(s.split())\nfor x in sorted((x for x in d if d[x] >= k), key=lambda x: (-d[x], -len(x), x)):\n    print(x, d[x])', [('2\nAna, mere! ana mere pere pere pere','pere 3\nmere 2\nana 2'),('2\nx y',''),('1\nb aa a','aa 1\na 1\nb 1')], 'Aplicare')
    add('colectii', 'Elevi: actualizare și raport', 'Citește n, apoi n linii cod nume nota1 nota2... (coduri distincte, cel puțin o notă). Ultima linie este un cod. Crește prima notă a acelui elev cu 1, fără a depăși 10. Afișează elevii ca nume medie, cu două zecimale, ordonați după medie descrescătoare și nume crescător.', 'Un dicționar indexat prin cod permite actualizarea directă; sortarea raportului folosește (-medie,nume).', 'n = int(input())\nd = {}\nfor _ in range(n):\n    cod, nume, *note = input().split()\n    d[cod] = [nume, list(map(int, note))]\ncod = input()\nif cod in d:\n    d[cod][1][0] = min(10, d[cod][1][0] + 1)\na = [(nume, sum(note) / len(note)) for nume, note in d.values()]\nfor nume, medie in sorted(a, key=lambda x: (-x[1], x[0])):\n    print(nume, f"{medie:.2f}")', [('2\n1 Ana 8 9\n2 Dan 9 9\n1','Ana 9.00\nDan 9.00'),('1\n1 Bob 10\n5','Bob 10.00'),('0\nx','')], 'Aplicare')
    add('functii', 'Cinema: șterge ore și filtrează', 'Citește n, apoi n linii cinema % film % ore (hh:mm). Citește apoi cinema % film % ora_de_sters, apoi cinematografele căutate separate prin %, apoi ora_min ora_max. Definește sterge_ore(d,cinema,film,ore) și cinema_film(d,ora_min,ora_max,*cinematografe). Afișează filmele rămase la cinema după ștergere, alfabetice, pe prima linie; apoi fiecare rezultat film % cinema % ore, sortat după film crescător, număr de ore descrescător și cinema crescător. Păstrează filmele chiar dacă nu mai au ore.', 'Folosește d[cinema][film] ca mulțime de ore. Formatul hh:mm permite comparația lexicografică a orelor.', 'def sterge_ore(d, cinema, film, ore):\n    if cinema in d and film in d[cinema]:\n        d[cinema][film] -= ore\n    return sorted(d.get(cinema, {}))\ndef cinema_film(d, ora_min, ora_max, *cinematografe):\n    a = []\n    for c in cinematografe:\n        for f, ore in d.get(c, {}).items():\n            o = sorted(x for x in ore if ora_min <= x <= ora_max)\n            if o:\n                a.append((f, c, o))\n    return sorted(a, key=lambda x: (x[0], -len(x[2]), x[1]))\nn = int(input())\nd = {}\nfor _ in range(n):\n    c, f, ore = (x.strip() for x in input().split("%"))\n    d.setdefault(c, {}).setdefault(f, set()).update(ore.split())\nc, f, o = (x.strip() for x in input().split("%"))\nprint(*sterge_ore(d, c, f, {o}))\ncs = [x.strip() for x in input().split("%")]\nmi, ma = input().split()\nfor f, c, ore in cinema_film(d, mi, ma, *cs):\n    print(f + " % " + c + " % " + " ".join(ore))', [('2\nCinema 1 % Film A % 10:00 18:00\nCinema 2 % Film A % 18:00 20:00\nCinema 1 % Film A % 10:00\nCinema 1 % Cinema 2\n14:00 22:00','Film A\nFilm A % Cinema 2 % 18:00 20:00\nFilm A % Cinema 1 % 18:00'),('1\nC % F % 09:00\nC % F % 09:00\nC\n00:00 23:59','F'),('1\nC % F % 12:00\nX % F % 12:00\nC\n12:00 12:00','\nF % C % 12:00')], 'Aprofundare', requiredFunctions=['sterge_ore','cinema_film'])
    add('functii', 'Magazine: prețuri și interogări', 'Citește n și apoi n linii magazin # categorie # preturi. Citește magazin # categorie # preturi_noi pentru înlocuire/adăugare, apoi magazinele căutate separate prin # și intervalul minim maxim. Definește actualizeaza_preturi și filtreaza_produse. Afișează categoriile magazinului actualizat, alfabetice, pe prima linie. Apoi afișează categorie # magazin # preturi din interval, cu două zecimale, sortate după categorie, număr de prețuri descrescător și magazin.', 'Structura este d[magazin][categorie]=lista_preturi. Filtrarea creează liste noi; nu modifică datele stocate.', 'def actualizeaza_preturi(d, magazin, categorie, preturi):\n    d.setdefault(magazin, {})[categorie] = preturi\n    return sorted(d[magazin])\ndef filtreaza_produse(d, minim, maxim, *magazine):\n    a = []\n    for m in magazine:\n        for c, p in d.get(m, {}).items():\n            v = sorted(x for x in p if minim <= x <= maxim)\n            if v:\n                a.append((c, m, v))\n    return sorted(a, key=lambda x: (x[0], -len(x[2]), x[1]))\nn = int(input())\nd = {}\nfor _ in range(n):\n    m, c, p = (x.strip() for x in input().split("#"))\n    d.setdefault(m, {})[c] = list(map(float, p.split()))\nm, c, p = (x.strip() for x in input().split("#"))\nprint(*actualizeaza_preturi(d, m, c, list(map(float, p.split()))))\nms = [x.strip() for x in input().split("#")]\nmi, ma = map(float, input().split())\nfor c, m, p in filtreaza_produse(d, mi, ma, *ms):\n    print(c + " # " + m + " # " + " ".join(f"{x:.2f}" for x in p))', [('1\nM # fructe # 4 6\nM # fructe # 3 5\nM\n4 5','fructe\nfructe # M # 5.00'),('0\nX # haine # 9\nX\n0 10','haine\nhaine # X # 9.00'),('1\nA # lapte # 5\nB # paine # 2\nA # B\n3 4','paine')], 'Aprofundare', requiredFunctions=['actualizeaza_preturi','filtreaza_produse'])
    add('fisiere', 'Două fișiere și similaritate cosinus', 'text1.in și text2.in conțin cuvinte lowercase. Scrie în date.out similaritatea cosinus a vectorilor de frecvență cu două zecimale. Dacă unul dintre texte nu are cuvinte, convenția acestui exercițiu este 0.00.', 'Counter construiește vectorii; produsul scalar se împarte la produsul normelor.', 'from collections import Counter\nfrom math import sqrt\nwith open("text1.in") as f:\n    a = Counter(f.read().split())\nwith open("text2.in") as f:\n    b = Counter(f.read().split())\nd = sqrt(sum(x * x for x in a.values()) * sum(x * x for x in b.values()))\ns = sum(a[x] * b[x] for x in a) / d if d else 0\nwith open("date.out", "w") as f:\n    print(f"{s:.2f}", file=f)', [(bundle(**{'text1.in':'a a b','text2.in':'a b b'}),'0.80'),(bundle(**{'text1.in':'x','text2.in':'y'}),'0.00'),(bundle(**{'text1.in':'','text2.in':'a'}),'0.00')], 'Aprofundare', inputFiles=['text1.in','text2.in'], outputFile='date.out')
    add('fisiere', 'Cuvânt în mai multe fișiere', 'a.in și b.in conțin text ASCII. Datele de la tastatură conțin cuvântul căutat. Definește cautare_cuvant(cuv,nume_fis_out,*nume_fis_in) și apeleaz-o pentru cele două fișiere. Scrie în date.out numele fiecărui fișier și liniile pe care apare cuvântul întreg, fără diferență între majuscule și minuscule. Semnele ,.!?;:- separă cuvintele. Dacă nu apare, scrie NU.', 'Normalizează fiecare linie și verifică tokenurile, nu simpla apariție ca subșir.', 'import re\ndef cautare_cuvant(cuv, nume_fis_out, *nume_fis_in):\n    with open(nume_fis_out, "w") as out:\n        for name in nume_fis_in:\n            with open(name) as f:\n                a = [i for i, line in enumerate(f, 1) if cuv.lower() in re.split(r"[ ,.!?;:\\-]+", line.strip().lower())]\n            print(name, *a if a else ["NU"], file=out)\ncautare_cuvant(input(), "date.out", "a.in", "b.in")', [(bundle(**{'a.in':'Floare albastra\nflori\nfloare!','b.in':'aceeasi floare','_stdin':'floare'}),'a.in 1 3\nb.in 1'),(bundle(**{'a.in':'xx','b.in':'x\nx','_stdin':'x'}),'a.in NU\nb.in 1 2'),(bundle(**{'a.in':'','b.in':'','_stdin':'a'}),'a.in NU\nb.in NU')], 'Aprofundare', inputFiles=['a.in','b.in'], outputFile='date.out', requiredFunction='cautare_cuvant')


